  skin_orbit: { en: 'Orbit', ru: 'Орбита', kk: 'Орбита' },
  skin_orbit_note: { en: 'Pro only. A live 3D scene under frosted glass. The camera moves as you change sections.', ru: 'Только для Pro. Живая 3D-сцена под матовым стеклом. Камера двигается, когда вы меняете раздел.', kk: 'Тек Pro үшін. Күңгірт әйнек астындағы тірі 3D-сахна. Бөлімді ауыстырғанда камера қозғалады.' },
  skin_plain: { en: 'Plain', ru: 'Обычная', kk: 'Қарапайым' },
  skin_plain_note: { en: 'Neutral greys, soft corners, quiet shadows. An interface that gets out of the way.', ru: 'Нейтральные серые, мягкие углы, тихие тени. Интерфейс, который не мешает.', kk: 'Бейтарап сұр түстер, жұмсақ бұрыштар, байсалды көлеңкелер. Кедергі келтірмейтін интерфейс.' },
  skin_editorial: { en: 'Editorial', ru: 'Редакция', kk: 'Редакция' },
  skin_editorial_note: { en: 'Warm paper, a serif for headings, hairline rules and almost no colour.', ru: 'Тёплая бумага, засечки в заголовках, тонкие линии и почти без цвета.', kk: 'Жылы қағаз, тақырыптарда серифті қаріп, жіңішке сызықтар және түс жоқтың қасы.' },
  skin_atelier: { en: 'Atelier', ru: 'Ателье', kk: 'Ателье' },
  skin_atelier_note: { en: 'No borders at all. Large radii and a wide, faint shadow; everything floats.', ru: 'Совсем без рамок. Большие скругления и широкая мягкая тень; всё парит.', kk: 'Мүлдем жиексіз. Үлкен дөңгелектер мен кең әлсіз көлеңке; бәрі қалқып тұрады.' },
  skin_brutal: { en: 'Brutalist', ru: 'Брутализм', kk: 'Брутализм' },
  skin_brutal_note: { en: 'Square corners, black rules, hard offset shadows and signal yellow.', ru: 'Прямые углы, чёрные линии, жёсткие смещённые тени и сигнальный жёлтый.', kk: 'Тік бұрыштар, қара сызықтар, қатты ығыстырылған көлеңкелер және сигнал сарысы.' },
  skin_terminal: { en: 'Terminal', ru: 'Терминал', kk: 'Терминал' },
  skin_terminal_note: { en: 'Monospace throughout, white phosphor on near-black, hazard red. Dark by construction.', ru: 'Моноширинный шрифт везде, белый люминофор на почти чёрном, тревожный красный. Тёмный по замыслу.', kk: 'Барлық жерде моноенді қаріп, қараға жуық фонда ақ жарық, дабыл қызылы. Әу бастан қараңғы.' },
  skin_marketplace: { en: 'Marketplace', ru: 'Маркетплейс', kk: 'Маркетплейс' },
  skin_marketplace_note: { en: 'Purple accents, four-pixel corners, one-pixel grey rules. Dense, made for scanning.', ru: 'Фиолетовые акценты, углы в четыре пикселя, серые линии в один пиксель. Плотный, для быстрого просмотра.', kk: 'Күлгін акценттер, төрт пиксельді бұрыштар, бір пиксельді сұр сызықтар. Тығыз, тез шолуға арналған.' },
  skin_academy: { en: 'Academy', ru: 'Академия', kk: 'Академия' },
  skin_academy_note: { en: 'One saturated blue doing every job, and no second accent.', ru: 'Один насыщенный синий делает всю работу, и никакого второго акцента.', kk: 'Барлық жұмысты бір қанық көк атқарады, екінші акцент жоқ.' },
  skin_streak: { en: 'Streak', ru: 'Стрик', kk: 'Стрик' },
  skin_streak_note: { en: 'Bright green, big radii, and buttons that drop into their own lip when pressed.', ru: 'Ярко-зелёный, большие скругления и кнопки, которые проваливаются при нажатии.', kk: 'Ашық жасыл, үлкен дөңгелектер және басқанда ішке батып кететін түймелер.' },
  skin_cinema: { en: 'Cinema', ru: 'Кино', kk: 'Кино' },
  skin_cinema_note: { en: 'Black and smoky black, one red on the thing to click.', ru: 'Чёрный и дымчато-чёрный, один красный — на том, что нужно нажать.', kk: 'Қара және түтінді қара, басу керек нәрседе бір қызыл.' },
  skin_poster: { en: 'Poster', ru: 'Плакат', kk: 'Плакат' },
  skin_poster_note: { en: 'Acid green and deep blue straight onto black and white. The loudest one.', ru: 'Кислотно-зелёный и глубокий синий прямо на чёрно-белом. Самый громкий.', kk: 'Қышқыл жасыл мен терең көк тікелей ақ-қараның үстінде. Ең шулысы.' },
  server_features: { en: 'Server features', ru: 'Серверные функции', kk: 'Серверлік функциялар' },
  what_needs_a_key: { en: 'What needs a key, and whether it has one. Values are never shown.', ru: 'Что требует ключа и есть ли он. Значения никогда не показываются.', kk: 'Неге кілт керек және ол бар ма. Мәндері ешқашан көрсетілмейді.' },
  configured: { en: 'Configured.', ru: 'Настроено.', kk: 'Бапталған.' },
  set_key_then_redeploy: { en: 'Set {key} in Vercel, then redeploy.', ru: 'Укажите {key} в Vercel и переразверните.', kk: 'Vercel-де {key} орнатып, қайта жариялаңыз.' },
  functions_not_deployed: { en: 'The server functions did not answer. On a static preview they are not running; deploy to Vercel or run `vercel dev`.', ru: 'Серверные функции не ответили. В статическом превью они не работают; разверните на Vercel или запустите `vercel dev`.', kk: 'Серверлік функциялар жауап бермеді. Статикалық алдын ала қарауда олар жұмыс істемейді; Vercel-ге жариялаңыз немесе `vercel dev` іске қосыңыз.' },
  feature_text: { en: 'Brand kits and copy (Pollinations)', ru: 'Брендбуки и тексты (Pollinations)', kk: 'Бренд-киттер мен мәтіндер (Pollinations)' },
  feature_images: { en: 'Images', ru: 'Изображения', kk: 'Суреттер' },
